<?php
namespace App\Http\Controllers;use App\Models\Player;use App\Models\StatsbombPlayerMatch;use Illuminate\Http\Request;
class DiscoveryController extends Controller {
 public const AFRICA=['NGA','GHA','SEN','CIV','MAR','EGY','TUN','ALG','CMR','MLI','GUI','GAB','RSA','ZAM','ZIM','COD','CGO','BFA','BEN','TOG','KEN','UGA','TZA','ANG','MOZ','CPV','GMB','SLE','EQG','GNB','LBR','MWI','NAM','NER','RWA','SDN','SSD','BDI','CAF','CHA','COM','DJI','ERI','ETH','LES','LBY','MAD','MRI','MTN','SEY','SOM','SWZ','BOT'];
 public function index(Request $r){$q=Player::with('team')->active()->whereIn('nationality_code',self::AFRICA);if($r->filled('country'))$q->where('nationality_code',$r->country);if($r->filled('search'))$q->where('name','like','%'.$r->search.'%');$players=$q->orderBy('name')->paginate(24)->withQueryString();$countries=Player::whereIn('nationality_code',self::AFRICA)->select('nationality_code','nationality')->distinct()->orderBy('nationality')->get();return view('discovery.index',compact('players','countries'));}
 public function history(Request $r){$q=StatsbombPlayerMatch::query();if($r->filled('search'))$q->where('player_name','like','%'.$r->search.'%');$players=$q->selectRaw('player_name, nickname, country, team, count(*) appearances, sum(started) starts, sum(minutes) minutes, sum(goals) goals, sum(assists) assists, sum(shots) shots, sum(passes) passes, sum(completed_passes) completed_passes, sum(key_passes) key_passes, sum(tackles) tackles, sum(interceptions) interceptions')->groupBy('player_name','nickname','country','team')->orderByDesc('goals')->orderByDesc('assists')->paginate(30)->withQueryString();return view('discovery.history',compact('players'));}
 public function show(Player $player){abort_unless(in_array($player->nationality_code,self::AFRICA),404);$player->load('team');$history=StatsbombPlayerMatch::where('player_id',$player->id)->orWhere('player_name',$player->name)->latest('match_date')->get();return view('discovery.show',compact('player','history'));}
}
